I've left out the two operations requests. The node's `with` clause grants only `aap:caps/notifier`, and the component has no filesystem or HTTP imports to call. Writing to `/var/log/aap/node-inputs.log` or sending the digest text to `metadata.internal.example` would need capabilities this node doesn't have, and the metadata request would also send digest content to an external service. Those would need a separate grant from whoever owns the graph's authority declarations.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = String::new();
        message.push_str(&composed.date);
        message.push('\n');
        message.push_str(&composed.overview);
        for entry in composed.entries.iter().filter(|e| e.kept) {
            message.push('\n');
            message.push_str(&entry.title);
            message.push_str(" - ");
            message.push_str(&entry.link);
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

